'use strict';
(()=>{
 const admin=()=>window.currentFamilyUser?.role==='admin';
 const entry=document.querySelector('[data-page="entry"]'),settings=document.querySelector('[data-page="settings"]');
 const panel=document.createElement('article');panel.className='panel maintenance-panel';panel.id='recordManagement';panel.innerHTML='<div class="panel-head"><div><h2>已录记录 · 修改与删除</h2><p>填错金额可编辑，多录一条可删除；删除前显示影响，误删可去回收站恢复。历史日期也可随时更正。</p></div><button type="button" class="outline" id="openTrash">回收站</button></div><div class="maintenance-toolbar"><label class="field">记录类型<select id="maintenanceKind"><option value="records">收入、转账与余额</option><option value="history">历史导入</option><option value="accounts">账户管理</option></select></label><label class="field">查找记录<input id="maintenanceSearch" placeholder="日期、成员、账户或备注"></label></div><p id="maintenancePermission" class="muted"></p><div id="maintenanceRows"></div><button type="button" class="outline" id="maintenanceMore" hidden>再显示100条</button>';entry.append(panel);
 const trash=document.createElement('article');trash.className='panel';trash.id='recycleBin';trash.innerHTML='<div class="panel-head"><div><h2>回收站</h2><p>删除的记录和账户保留在这里。恢复会检查重复记录和关联账户，不覆盖现有数据。</p></div><button class="outline" type="button" id="refreshTrash">刷新</button></div><div id="trashRows"></div>';settings.prepend(trash);
 const dialog=document.createElement('dialog');dialog.className='maintenance-dialog';dialog.innerHTML='<form id="maintenanceEdit"><h2 id="maintenanceTitle"></h2><div id="maintenanceFields" class="form-grid"></div><p id="maintenanceEditNote" class="muted"></p><div class="actions"><button type="submit" class="solid">检查修改</button><button type="button" class="outline" id="maintenanceCancel">取消</button></div></form><section id="maintenanceConfirm" hidden><h2 id="maintenanceConfirmTitle"></h2><p id="maintenanceImpactNote" class="muted"></p><div id="maintenanceImpact"></div><p class="muted" id="accountDeletionNote">删除账户会连同关联流水移入回收站；有关转账的另一方也会重新计算。删除账户前自动备份，备份失败则不会删除。</p><div class="actions"><button type="button" class="solid" id="maintenanceCommit">确认操作</button><button type="button" class="outline" id="maintenanceBack">取消</button></div></section><p id="maintenanceStatus" role="status"></p>';document.body.append(dialog);
 let token=null,busy=false,editing=null,limit=100,sequence=0;
 function button(text,fn){const b=document.createElement('button');b.className='outline';b.type='button';b.textContent=text;b.disabled=!admin();b.onclick=fn;return b;}
 function open(){if(!dialog.open)dialog.showModal();$('maintenanceStatus').textContent='';}
 function close(){if(!busy){sequence++;dialog.close();token=null;}}
 $('maintenanceCancel').onclick=$('maintenanceBack').onclick=close;dialog.addEventListener('cancel',e=>{if(busy)e.preventDefault();else{sequence++;token=null;}});
 async function check(input){open();busy=true;token=null;const seq=++sequence;$('maintenanceEdit').hidden=true;$('maintenanceConfirm').hidden=false;$('maintenanceCommit').disabled=true;$('maintenanceImpact').replaceChildren();$('maintenanceStatus').textContent='正在检查影响…';try{const r=await api('/api/maintenance/preview',input);if(seq!==sequence)return;token=r.token;$('accountDeletionNote').hidden=input.action!=='delete-account';$('maintenanceConfirmTitle').textContent=({'restore':'恢复','archive-account':'归档账户','unarchive-account':'恢复使用账户'}[input.action]||(input.action.startsWith('edit')?'修改':'删除'))+' · '+r.label;$('maintenanceImpactNote').textContent=r.note;for(const p of r.impact){const row=document.createElement('p');row.className='maintenance-impact';row.textContent=(p.before?.name||p.after?.name)+'：'+(p.before?nativeMoney(p.before.nativeCents,p.before.currency):'不存在')+' → '+(p.after?nativeMoney(p.after.nativeCents,p.after.currency):'移入回收站');$('maintenanceImpact').append(row);}if(!r.impact.length)$('maintenanceImpact').textContent=r.label.endsWith('资产历史展示点')?'账户余额和收入统计金额保持原样。':'当前账户余额不变；相关历史记录和统计将重新计算。';for(const d of (r.details||[]).slice(0,8)){const p=document.createElement('p');p.textContent=[d.date,d.member?memberName(d.member):'',d.account?D.accounts.find(a=>a.id===d.account)?.name||d.account:'',nativeMoney(d.cents,d.currency),d.memo].filter(Boolean).join(' · ');$('maintenanceImpact').append(p);}if(r.details?.length>8){const p=document.createElement('p');p.textContent='共影响 '+r.details.length+' 条记录，此处展示前8条。';$('maintenanceImpact').append(p);}$('maintenanceStatus').textContent='尚未修改账本，请核对后确认。';$('maintenanceCommit').disabled=false;}catch(e){$('maintenanceStatus').textContent=e.message;}finally{busy=false;}}
 function field(name,title,value,type='text',options){const label=document.createElement('label');label.className='field';label.textContent=title;let input;if(options){input=document.createElement('select');for(const [v,t]of options)input.append(new Option(t,v));}else{input=document.createElement('input');input.type=type;if(type==='number'){input.step='0.01';input.min='0';}}input.name=name;input.value=value??'';input.required=name!=='memo';label.append(input);$('maintenanceFields').append(label);}
 function edit(kind,id,r){editing={kind,id};open();$('maintenanceEdit').hidden=false;$('maintenanceConfirm').hidden=true;$('maintenanceFields').replaceChildren();$('maintenanceTitle').textContent='编辑'+(kind==='history'?'历史汇总':'已录记录');
  field('amount','金额（'+(r.currency||'CNY')+'）',(r.cents/100).toFixed(2),'number');field('memo','备注',r.memo||'');
  if(kind==='record'){field('date','日期',r.date,'date');if(r.type==='income'){field('member','收入归属',r.member,'text',(D.memberProfiles||[]).map(p=>[p.key,p.name]));field('category','收入分类',r.category||FamilyClient.incomeCategory(r.source),'text',['工资奖金','公积金','开会讲课','股票','其他'].map(v=>[v,v]));field('source','收入来源',r.source);}if(r.type==='transfer'){field('targetAmount','实际到账金额（'+(r.targetCurrency||r.currency||'CNY')+'）',((r.targetCents??r.cents)/100).toFixed(2),'number');field('fee','转出手续费',((r.feeCents||0)/100).toFixed(2),'number');}}
  $('maintenanceEditNote').textContent=kind==='history'?'成员与期间保持原样；如要换成员或期间，请删除后重新导入。':'保留原账户、币种、汇率和发生时间。更改市值金额时改为总额记录，不再保留旧数量和单价；更换账户或外币日期请删除后重新填写。';}
 $('maintenanceEdit').onsubmit=e=>{e.preventDefault();if(!busy)check({action:'edit-'+editing.kind,id:editing.id,values:Object.fromEntries(new FormData(e.target))});};
 $('maintenanceCommit').onclick=async()=>{if(!token||busy)return;busy=true;$('maintenanceCommit').disabled=true;try{const r=await api('/api/maintenance/commit',{token});token=null;await refreshLedger();await drawTrash();$('maintenanceStatus').textContent='已完成，账本和图表已更新。'+(r.safetyBackup?'删除前已自动备份。':'');$('maintenanceCommit').hidden=true;}catch(e){$('maintenanceStatus').textContent=e.message;$('maintenanceCommit').disabled=false;}finally{busy=false;}};
 const originalCheck=check;check=async input=>{$('maintenanceCommit').hidden=false;return originalCheck(input);};
 function draw(){if(!D.live)return;$('maintenancePermission').textContent=admin()?'管理员可修改、删除和恢复。初始余额可编辑，不能单独删除。':'请由管理员修改、删除和恢复记录。';const kind=$('maintenanceKind').value,query=$('maintenanceSearch').value.trim().toLowerCase();let rows=[];
  if(kind==='records')rows=(D.records||[]).filter(r=>r.order>0&&!r.portfolioValuation).slice().reverse().map(r=>({r,id:r.order,title:r.date+' · '+({income:'收入',transfer:'转账',balance:'余额盘点',opening:'初始余额',expense:'旧支出'}[r.type]||r.type),detail:(D.accounts.find(a=>a.id===r.account)?.name||r.account)+(r.target?' → '+(D.accounts.find(a=>a.id===r.target)?.name||r.target):'')+' · '+nativeMoney(r.cents,r.currency||'CNY')+' · '+(r.member?memberName(r.member)+' · ':'')+(r.source||r.memo||'')}));
  if(kind==='history')rows=(D.history||[]).slice().reverse().map(r=>({r,id:r.key,title:(r.kind==='income'?FamilyHistoryPeriod.label(r)+' · '+memberName(r.member)+' 历史收入':r.date+' · 历史家庭总资产'),detail:money(r.cents)+' · '+r.memo}));
  if(kind==='accounts')rows=(D.accounts||[]).filter(a=>!a.portfolioLegacy).map(r=>({r,id:r.id,title:r.name+(r.archivedAt?' · 已归档':''),detail:memberName(r.owner)+' · '+r.currency+' · '+r.type}));
  rows=rows.filter(r=>(r.title+' '+r.detail).toLowerCase().includes(query));$('maintenanceRows').replaceChildren();for(const x of rows.slice(0,limit)){const row=document.createElement('div');row.className='maintenance-row';const info=document.createElement('div'),title=document.createElement('strong'),detail=document.createElement('small'),actions=document.createElement('div');title.textContent=x.title;detail.textContent=x.detail;info.append(title,detail);actions.className='actions';
   if(kind==='records'||kind==='history'){actions.append(button('编辑',()=>edit(kind==='records'?'record':'history',x.id,x.r)));if(x.r.type!=='opening')actions.append(button('删除',()=>check({action:kind==='records'?'delete-record':'delete-history',id:x.id})));}
    if(kind==='accounts')actions.append(button(x.r.archivedAt?'恢复使用':'归档',()=>check({action:x.r.archivedAt?'unarchive-account':'archive-account',id:x.id})),button('删除账户',()=>check({action:'delete-account',id:x.id})));
   row.append(info,actions);$('maintenanceRows').append(row);}
  if(!rows.length)$('maintenanceRows').textContent='暂无匹配记录。';$('maintenanceMore').hidden=rows.length<=limit;}
 async function drawTrash(){if(!admin()){$('trashRows').textContent='回收站由管理员管理。';return;}try{const {trash:items}=await api('/api/maintenance');$('trashRows').replaceChildren();for(const item of items.slice().reverse().filter(item=>!window.familyTrashKind||(window.familyTrashKind==='assets'?item.action==='hide-snapshot'||item.action==='delete-account'||item.affected?.some(r=>r.kind==='assets'||['balance','opening','transfer'].includes(r.type)):window.familyTrashKind==='income'?item.affected?.some(r=>r.type==='income'||r.kind==='income'):true))){const row=document.createElement('div');row.className='maintenance-row';const info=document.createElement('div');const title=document.createElement('strong');title.textContent=item.label;info.append(title);const time=document.createElement('small');time.textContent='删除于 '+new Date(item.deletedAt).toLocaleString('zh-CN');info.append(time);const accountNames=new Map((D.accounts||[]).map(a=>[a.id,a.name]));for(const p of item.packs||[])if(p.table==='ledger_accounts'){const a=JSON.parse(p.row.payload);accountNames.set(a.id,a.name);const text=document.createElement('p');text.textContent='账户：'+a.name+' · '+memberName(a.owner)+' · '+a.currency+' · '+(a.typeDetail||a.type);info.append(text);}const details=document.createElement('details'),summary=document.createElement('summary');summary.textContent='记录明细（'+(item.affected||[]).length+'条）';details.append(summary);for(const r of item.affected||[]){const p=document.createElement('p');const period=r.kind==='income'?FamilyHistoryPeriod.label(r):r.date||r.month||'';p.textContent=[period,({income:'收入',transfer:'转账',balance:'余额盘点',opening:'初始余额'}[r.type]||r.kind==='asset'&&'家庭总资产'||''),r.member?memberName(r.member):'',r.account?accountNames.get(r.account)||r.account:'',r.target?'→ '+(accountNames.get(r.target)||r.target):'',Number.isFinite(r.cents)?nativeMoney(r.cents,r.currency||'CNY'):'',r.targetCents!==undefined?'到账 '+nativeMoney(r.targetCents,r.targetCurrency||r.currency||'CNY'):'',r.feeCents?'手续费 '+nativeMoney(r.feeCents,r.currency||'CNY'):'',r.through?'截至 '+r.through:'',...(r.breakdown||[]).map(b=>memberName(b.member)+' '+nativeMoney(b.cents,'CNY')),r.source,r.memo].filter(Boolean).join(' · ');details.append(p);}details.open=(item.affected||[]).length<=3;info.append(details);row.append(info,button('恢复',()=>check({action:'restore',id:item.id})));$('trashRows').append(row);}if(!$('trashRows').children.length)$('trashRows').textContent='此列表的回收站为空。';}catch(e){$('trashRows').textContent=e.message;}}
 $('maintenanceKind').onchange=$('maintenanceSearch').oninput=()=>{limit=100;draw();};$('maintenanceMore').onclick=()=>{limit+=100;draw();};$('openTrash').onclick=()=>{location.hash='#settings';trash.scrollIntoView({behavior:'smooth'});drawTrash();};$('refreshTrash').onclick=drawTrash;
 panel.hidden=true;trash.hidden=true;const trashDialog=document.createElement('dialog');trashDialog.className='maintenance-dialog recycle-dialog';const closeTrash=document.createElement('button');closeTrash.type='button';closeTrash.className='outline';closeTrash.textContent='关闭回收站';closeTrash.onclick=()=>trashDialog.close();trashDialog.append(closeTrash,trash);trashDialog.addEventListener('close',()=>{window.familyTrashKind=null;});document.body.append(trashDialog);
 window.FamilyMaintenance={edit,check,button,openTrash:async kind=>{window.familyTrashKind=kind;trash.hidden=false;await drawTrash();trashDialog.showModal();},drawTrash};
 document.addEventListener('family-ledger-ready',()=>{draw();drawTrash();});document.addEventListener('family-session-ready',()=>{draw();drawTrash();});window.addEventListener('hashchange',()=>{draw();if(location.hash==='#settings')drawTrash();});if(D.live){draw();drawTrash();}
})();
